"use client";

// The four-topic intraday study (Nov 2026): 48 YouTube videos on NIFTY option buying, NSE stock intraday, bitcoin and
// MCX commodity intraday turned into exact rules. Data: ./intraday4Data.ts, generated by
// backend/research/youtube_intraday4_2026_11/zd_export.py from the study's cards (the Trading Video Lab's card format).
// Research only: the coded strategies passed the look-ahead and fill checks; none is backtested or on the paper desk yet.
import { useMemo, useState } from "react";
import GlassPanel from "../../components/GlassPanel";
import { I4, I4_META, type I4Rule, type I4Strategy } from "./intraday4Data";

const TOPICS = [
  { id: "nifty_option_buying", label: "NIFTY option buying",
    note: "Option-buying setups on NIFTY. The desk has no intraday option premiums, so each coded one trades the NIFTY index as a labelled proxy with the delta its card states; strategies that need the premiums themselves are blocked below." },
  { id: "stock_intraday", label: "Indian stock intraday",
    note: "NSE stock setups on the desk's 5-minute stock pool (and NIFTY / Bank Nifty where the video teaches the index). Sector and option-chain rules the pool cannot see are documented as dropped." },
  { id: "btc_intraday", label: "Bitcoin intraday",
    note: "Bitcoin setups for Delta Exchange's BTCUSD perpetual: one-minute data, the UTC day, every book flat by 23:55 UTC. Five of the twelve videos repeated strategies the library already holds." },
  { id: "commodity_intraday", label: "MCX commodity intraday",
    note: "MCX crude oil, natural gas and silver micro setups for the 09:00-23:30 IST session. The paper desk has no MCX feed yet: the code was checked on a stand-in series cut to MCX hours, and these books need an MCX (or NYMEX) feed before they can paper trade." },
] as const;
type TopicId = (typeof TOPICS)[number]["id"];

function sec(t: string): number {
  const p = t.split(":").map(Number);
  return p.length === 3 ? p[0] * 3600 + p[1] * 60 + p[2] : p[0] * 60 + p[1];
}

function Times({ video, times }: { video: string; times: string[] }) {
  if (!times.length) return null;
  return (
    <span className="i4-times">
      {times.map((t, i) => (
        <a key={`${t}-${i}`} href={`https://youtu.be/${video}?t=${sec(t)}`} target="_blank" rel="noreferrer">{t}</a>
      ))}
    </span>
  );
}

function grouped(rules: I4Rule[]): [string, I4Rule[]][] {
  const out: [string, I4Rule[]][] = [];
  for (const r of rules) {
    const last = out[out.length - 1];
    if (last && last[0] === r.label) last[1].push(r);
    else out.push([r.label, [r]]);
  }
  return out;
}

function Card({ s }: { s: I4Strategy }) {
  const stated = s.rules.filter((r) => r.tag !== "A");
  const ours = s.rules.filter((r) => r.tag === "A");
  const gaps = s.vague.length + s.unclear.length;
  return (
    <div className="ps-card i4-card">
      <div className="ps-card-top">
        <span className="ps-fam up">{s.id} · {s.version}</span>
        <span className="i4-state">Not on the paper desk yet</span>
      </div>
      <div className="ps-card-name">{s.name}</div>
      <div className="i4-line">{s.markets.join(" · ")} · {s.timeframes.join(", ")}{s.overnight ? " · may hold across sessions" : " · intraday"}</div>
      {s.proxy && <div className="i4-proxy">{s.proxy}.</div>}
      <div className="i4-line">
        <a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.title || s.video}</a>
        <span className="i4-dim"> · {s.channel}{s.uploaded ? ` · ${s.uploaded}` : ""}{s.minutes ? ` · ${s.minutes} min` : ""}</span>
      </div>
      <p className="i4-sum">{s.summary}</p>
      <div className="i4-tags">
        <span className={`i4-tag ${s.readiness === "ready" ? "ok" : "warn"}`}>{s.readiness === "ready" ? "Every rule stated" : "Coded with documented assumptions"}</span>
        {s.checks && (
          <span className={`i4-tag ${s.checks.lookahead && s.checks.fills ? "ok" : "bad"}`}>
            {s.checks.lookahead && s.checks.fills ? "Look-ahead and fill checks passed" : "Code check failed"}
          </span>
        )}
        <span className="i4-tag">Not backtested</span>
      </div>

      <details className="i4-sec" open>
        <summary>Rules from the video ({stated.length})</summary>
        {grouped(stated).map(([label, rs]) => (
          <div key={label} className="i4-group">
            <div className="i4-glabel">{label}</div>
            <ul className="i4-rules">
              {rs.map((r, i) => (
                <li key={i}><span className={`i4-t ${r.tag}`}>{r.tag}</span> {r.text} <Times video={s.video} times={r.times} /></li>
              ))}
            </ul>
          </div>
        ))}
      </details>
      {ours.length > 0 && (
        <details className="i4-sec">
          <summary>Our assumptions used to code it ({ours.length})</summary>
          <ul className="i4-rules">
            {ours.map((r, i) => <li key={i}><span className="i4-t A">A</span> {r.text}</li>)}
          </ul>
          <p className="i4-dim">These are the research team&apos;s choices, not the creator&apos;s words: they fill the gaps the video leaves so the rule can run.</p>
        </details>
      )}
      {gaps > 0 && (
        <details className="i4-sec">
          <summary>Missing or ambiguous in the video ({gaps})</summary>
          <ul className="i4-rules">
            {s.vague.map((v, i) => (
              <li key={`v${i}`}>&ldquo;{v.term}&rdquo; <Times video={s.video} times={v.at ? [v.at] : []} />: {v.why}. Coded as: {v.suggestion}.</li>
            ))}
            {s.unclear.map((u, i) => <li key={`u${i}`}>Open question: {u}</li>)}
          </ul>
        </details>
      )}
      {(s.claims.length > 0 || s.examples.length > 0) && (
        <details className="i4-sec">
          <summary>Claims and examples in the video ({s.claims.length + s.examples.length})</summary>
          <ul className="i4-rules">
            {s.claims.map((c, i) => (
              <li key={`c${i}`}>Claim: {c.value}{c.period ? ` (${c.period})` : ""} <Times video={s.video} times={c.at ? [c.at] : []} /></li>
            ))}
            {s.examples.map((x, i) => (
              <li key={`x${i}`}>
                Example{x.date ? ` ${x.date}` : ""}: {x.instrument} {x.direction} — {x.setup}; entry {x.entry || "—"}, stop {x.stop || "—"}, target {x.target || "—"} → {x.outcome}
                {x.note ? ` (${x.note})` : ""} <Times video={s.video} times={x.at ? [x.at] : []} />
              </li>
            ))}
          </ul>
          <p className="i4-dim">Quoted as said and not verified.</p>
        </details>
      )}
      {s.checks && (
        <div className="i4-dim">Code check windows: {s.checks.signals} signals, {s.checks.trades} simulated fills (a correctness check, not a result).</div>
      )}
    </div>
  );
}

export default function Intraday4() {
  const [topic, setTopic] = useState<TopicId>("nifty_option_buying");
  const [q, setQ] = useState("");
  const T = TOPICS.find((t) => t.id === topic)!;
  const ql = q.trim().toLowerCase();
  const inTopic = useMemo(() => I4.filter((s) => s.topic === topic), [topic]);
  const coded = inTopic.filter((s) => s.status === "coded" && (!ql || `${s.id} ${s.name} ${s.channel} ${s.title}`.toLowerCase().includes(ql)));
  const blocked = inTopic.filter((s) => s.status === "blocked");
  const dups = inTopic.filter((s) => s.status === "duplicate");
  const m = I4_META;
  return (
    <>
      <GlassPanel title="48 more YouTube videos — four intraday topics" note={`${m.coded} coded · ${m.blocked} blocked · ${m.duplicates} duplicates · research only`}>
        <p className="i4-intro">
          {m.queries} YouTube searches across NIFTY intraday option buying, Indian stock intraday, bitcoin intraday and MCX commodity intraday found{" "}
          {m.found.toLocaleString("en-IN")} videos; {m.covered_before} of them had already been covered by earlier studies and were skipped. {m.selected}{" "}
          videos (12 per topic) were chosen for complete-looking rules and read in full from their transcripts in the Trading Video Lab, one strategy card each
          (every rule tagged as stated, inferred or our assumption, with the time in the video). That gave {m.strategies} strategies: {m.coded} coded as exact
          rules (version v1), {m.blocked} blocked because they need data the desk does not have or give no testable rule, and {m.duplicates} that repeat a
          strategy the library already holds (not added again). All {m.lookahead_ok} coded strategies passed the look-ahead and fill checks. None has been
          backtested or put on the paper desk yet; {m.backups_queued} backup videos are queued, not analysed.
        </p>
      </GlassPanel>
      <div className="ps-chips i4-topics">
        {TOPICS.map((t) => {
          const n = I4.filter((s) => s.topic === t.id);
          return (
            <button key={t.id} className={`ps-chip${topic === t.id ? " on" : ""}`} onClick={() => setTopic(t.id)}>
              {t.label} · {n.filter((s) => s.status === "coded").length} coded / {n.length}
            </button>
          );
        })}
        <input className="i4-q" placeholder="Search id, name, channel" value={q} onChange={(e) => setQ(e.target.value)} />
      </div>
      <p className="i4-note">{T.note}</p>
      <div className="ps-cards i4-cards">
        {coded.map((s) => <Card key={s.id} s={s} />)}
      </div>
      {blocked.length > 0 && (
        <GlassPanel title={`Blocked in ${T.label}`} note="no account: the rule needs data the desk lacks, or gives no testable rule">
          <ul className="i4-list">
            {blocked.map((s) => (
              <li key={s.id}>
                <b>{s.id} {s.name}</b> (<a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.channel || s.video}</a>) — {s.blockedReason}
                <details className="i4-sec">
                  <summary>Its rules as the video gives them ({s.rules.length})</summary>
                  <ul className="i4-rules">
                    {s.rules.map((r, i) => <li key={i}><span className={`i4-t ${r.tag}`}>{r.tag}</span> <b>{r.label}:</b> {r.text} <Times video={s.video} times={r.times} /></li>)}
                  </ul>
                </details>
              </li>
            ))}
          </ul>
        </GlassPanel>
      )}
      {dups.length > 0 && (
        <GlassPanel title={`Duplicates of the library in ${T.label}`} note="not added again">
          <ul className="i4-list">
            {dups.map((s) => (
              <li key={s.id}>
                <b>{s.id} {s.name}</b> (<a href={`https://youtu.be/${s.video}`} target="_blank" rel="noreferrer">{s.channel || s.video}</a>) — repeats{" "}
                <b>{s.duplicateOf}</b>: {s.duplicateWhy}.
              </li>
            ))}
          </ul>
        </GlassPanel>
      )}
      {/* global: the cards are a child component; every selector is i4-prefixed, so nothing outside this tab is touched. */}
      <style jsx global>{`
        .i4-intro { font-size: 13px; line-height: 1.6; color: var(--text-muted); margin: 0; }
        .i4-topics { margin: 14px 0 6px; align-items: center; }
        .i4-q { margin-left: auto; min-width: 200px; padding: 6px 10px; border-radius: 8px; border: 1px solid var(--panel-border);
          background: transparent; color: inherit; font-size: 12.5px; }
        .i4-note { font-size: 12.5px; color: var(--text-muted); margin: 4px 0 12px; line-height: 1.5; }
        .i4-cards { align-items: start; margin-bottom: 16px; }
        .i4-line { font-size: 12.5px; line-height: 1.5; overflow-wrap: anywhere; }
        .i4-dim { color: var(--text-muted); font-size: 11.5px; }
        .i4-sum { font-size: 12.5px; line-height: 1.55; margin: 0; color: var(--text-secondary); }
        .i4-state { font-size: 11px; color: var(--text-muted); }
        .i4-proxy { font-size: 12px; padding: 6px 8px; border-radius: 6px; background: var(--warn-dim); color: var(--warn); }
        .i4-tags { display: flex; flex-wrap: wrap; gap: 6px; }
        .i4-tag { font-size: 11px; padding: 2px 8px; border-radius: 999px; border: 1px solid var(--panel-border); color: var(--text-muted); }
        .i4-tag.ok { border-color: var(--gain); color: var(--gain); }
        .i4-tag.warn { border-color: var(--warn-border); color: var(--warn); }
        .i4-tag.bad { border-color: var(--loss); color: var(--loss); }
        .i4-sec { font-size: 12.5px; }
        .i4-sec summary { cursor: pointer; font-weight: 600; }
        .i4-group { margin-top: 6px; }
        .i4-glabel { font-size: 11px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase; color: var(--text-muted); }
        .i4-rules { margin: 4px 0 6px; padding-left: 18px; line-height: 1.55; }
        .i4-rules li { margin-bottom: 4px; overflow-wrap: anywhere; }
        .i4-t { display: inline-block; min-width: 16px; text-align: center; font-size: 10px; font-weight: 800; border-radius: 4px; padding: 0 3px;
          border: 1px solid var(--panel-border); color: var(--text-muted); }
        .i4-t.E { border-color: var(--gain); color: var(--gain); }
        .i4-t.I { border-color: var(--purple); color: var(--purple); }
        .i4-t.A { border-color: var(--warn-border); color: var(--warn); }
        .i4-times a { margin-left: 6px; font-size: 11px; font-variant-numeric: tabular-nums; }
        .i4-list { font-size: 12.5px; line-height: 1.6; padding-left: 18px; margin: 0; }
        .i4-list li { margin-bottom: 8px; overflow-wrap: anywhere; }
      `}</style>
    </>
  );
}
